 using Json=eventio::Json;const char*key="runtime_source_curve_coverage_v1";if(!cfg.contains(key))return {{"requested",false}};auto require=[](bool ok,const std::string&why){if(!ok)throw std::runtime_error("cap168 source coverage: "+why);};
 auto pin=[&](const Json&ref){auto f=std::filesystem::u8path(ref.at("file").get<std::string>());require(f.is_absolute(),"evidence ref is not absolute");f=JointExactDependencyAliasesV1::resolve(f,ref.at("sha256").get<std::string>());runtime_primitive_release_detail_v1::pin(f,ref.at("sha256").get<std::string>());return f;};
 const auto request=eventio::read_json(pin(cfg.at(key)));require(request.at("schema")=="rinkfit.source_supported_engineering_cap_domain_request.v1"&&request.at("requests").size()==1,"unsupported source coverage request");pin(request.at("source_packet"));pin(request.at("source_geometry_qualification"));const auto original=eventio::read_json(pin(request.at("activity_model")));require(request.at("source_packet").at("sha256")==p.source_hash&&request.at("source_packet").at("sha256")==eventio::file_sha256(packet_file)&&request.at("activity_model").at("sha256")==eventio::file_sha256(model_file)&&original==m.source_json&&m.exact_json()==original,"request is not the actual unchanged a0/q6 post-prefix state");require(request.at("source_geometry_qualification").at("sha256")==cfg.at("dense_source_qualification").at("sha256")&&std::filesystem::equivalent(pin(request.at("source_geometry_qualification")),pin(cfg.at("dense_source_qualification"))),"request qualification generation differs");for(const auto&ref:request.at("actual_input_references"))pin(ref);
 const auto&r=request.at("requests").at(0);require(r.at("material_index")==168&&r.at("path_index")==1&&r.at("geometry_block")==40&&r.at("preserve_geometry_indices")==Json::array({0,1,2,3})&&r.at("change_geometry_indices")==Json::array({4,5})&&r.at("physical_endpoint")=="unknown"&&r.at("numerical_coverage_only")==true&&r.at("infinite_extension_permitted")==false&&r.at("extension_claimed_observed_at_every_world_station")==false&&r.at("old_source_UV_ID_PTS_Query_W_qualification_unchanged")==true&&r.at("old_world_points_preserved_by_linear_station_rechart")==true,"request is not a bounded unknown engineering cap");
 auto&block=m.blocks.at(40);require(block.name=="ice/line/w036"&&block.constant&&block.values.size()==6,"target primitive registry/lock changed");const auto before_block=block.values;const auto&material=m.materials.at(168);const auto&path=material.paths.at(1);require(material.label==r.at("material_label")&&path.id==r.at("path_id")&&path.kind==0&&!path.physical_point&&path.geometry_block==40&&m.path_geometry_indices.at({168,1})==std::vector<int>({2,3,4,5})&&m.path_geometry_indices.at({168,0})==std::vector<int>({0,1,2,3}),"actual target finite paths differ");const auto provenance=Json::parse(path.provenance);require(provenance.at("physical_endpoint")=="unknown"&&provenance.at("numerical_coverage_cap")==true&&provenance.at("old_carrier_preserved")==true,"a measured endpoint cannot be extended");
 for(std::size_t mi=0;mi<m.materials.size();++mi)for(std::size_t pi=0;pi<m.materials[mi].paths.size();++pi){const auto&v=m.materials[mi].paths[pi];if(v.geometry_block!=40)continue;const auto it=m.path_geometry_indices.find({int(mi),int(pi)});const auto indices=it==m.path_geometry_indices.end()?std::vector<int>{0,1,2,3}:it->second;for(int j:indices)if(j==4||j==5)require(mi==168&&pi==1,"another material consumes the cap tail scalars");}
 const auto A=r.at("old_carrier_A").get<std::array<double,2>>(),B=r.at("old_carrier_B").get<std::array<double,2>>(),C=r.at("old_endpoint").get<std::array<double,2>>(),D=r.at("bounded_new_endpoint").get<std::array<double,2>>();require(before_block==std::vector<double>({A[0],A[1],B[0],B[1],C[0],C[1]}),"old carrier/cap bytes differ");const auto scene=m.blocks.at(m.scene_block).values;require(m.scene_block==r.at("scene_block")&&scene==r.at("scene_values").get<std::vector<double>>()&&r.at("boundary")=="current_ice_right_straight_end"&&D[0]==.5&&std::abs(D[1])<=scene[0]/2-scene[2],"new engineering cap is outside the finite current right straight end");const double abx=B[0]-A[0],aby=B[1]-A[1],tC=(C[0]-A[0])/abx,tD=(D[0]-A[0])/abx,scale=(tC-1)/(tD-1);require(std::isfinite(scale)&&scale>0&&scale<1&&tD>tC&&std::abs(A[1]+tC*aby-C[1])<1e-14&&std::abs(A[1]+tD*aby-D[1])<1e-14&&std::abs(scale-r.at("old_station_to_new_scale").get<double>())<2e-15,"nonpositive/off-carrier/unbounded station rechart");for(int j=0;j<2;++j)require(D[j]>=block.lower[4+j]&&D[j]<=block.upper[4+j],"new cap is outside existing serialized boxes");
 const auto source=eventio::read_json(pin(r.at("source_evidence")));require(source.at("schema")=="rinkfit.source_continuation_cap_local_case.v1"&&source.at("source_packet")==request.at("source_packet")&&source.at("source_geometry_qualification")==request.at("source_geometry_qualification")&&source.at("new_source_rows_or_UV_issued")==false&&source.at("qualification_changed")==false&&source.at("reflection_or_human_pixels_added")==false&&source.at("source_profile_is_not_world_endpoint_or_station")==true,"source review changes point facts or claims a world endpoint");for(const char*k:{"original_RGB","same_local_straight_material_continuity_review","original_source_guide","current_source_profile_receipt"})pin(source.at(k));for(const auto&item:source.at("rows")){const auto i=item.at("packet_row").get<std::size_t>();const auto&o=p.rows.at(i);require(o.active&&o.source_row_id==item.at("selected_row_id")&&o.pts==item.at("native_pts")&&o.uv==item.at("source_UV").get<std::array<double,2>>()&&o.material==168&&o.path==1&&item.at("source_center_clear")==true&&item.at("source_profile_reproduction_distance_px")==0,"actual continuation source row mismatch");pin(item.at("review"));}
 struct Saved{std::size_t i;double station;Vec3<double>world;Vec2<double>uv;bool arithmetic;};std::vector<Saved>saved;std::size_t prefix_active=0,S01_cap=0;const auto prefix=p.source_json.at("dense_source_binding").at("row_start").get<std::size_t>();auto world=[&](const JointObservation&o,double s){const auto l=o.layout(m);const auto ptr=m.pointers(l);auto g=m.global(l,ptr.data());std::vector<const double*>q;std::vector<double>geometry;const auto legacy=m.legacy_layout(l,q,g,ptr.data(),geometry);return m.world_point(l,s,q.data(),legacy,m.shots.at(l.shot_index).math);};
 for(std::size_t i=0;i<p.rows.size();++i){const auto&o=p.rows[i];if(o.material!=168||o.path!=1)continue;require(std::isfinite(o.station)&&o.station>=0&&o.station<=1,"old finite station is outside its chart");const auto l=o.layout(m);const auto ptr=m.pointers(l);const auto pred=m.predict_for_al(l,o.station,o.row,ptr.data());saved.push_back({i,o.station,world(o,o.station),pred.uv,pred.arithmetic_valid});prefix_active+=i<prefix&&o.active;S01_cap+=o.active&&o.shot_id=="s01";}
 require(!saved.empty()&&S01_cap==0&&S01_cap==r.at("S01_actual_cap_scalar_active_references").get<std::size_t>()&&prefix_active==r.at("parent_active_path1_rows_requiring_rechart").get<std::size_t>(),"actual parent/S01 cap dependency counts differ");
 block.values[4]=D[0];block.values[5]=D[1];double max_world=0,max_uv=0;std::size_t active_UV_verified=0;std::vector<std::uint64_t>indices;std::vector<double>old_stations,new_stations;for(const auto&old:saved){auto&o=p.rows[old.i];o.station=old.station*scale;const auto current=world(o,o.station);for(int k=0;k<3;++k)max_world=std::max(max_world,std::abs(current[k]-old.world[k]));const auto l=o.layout(m);const auto ptr=m.pointers(l);const auto pred=m.predict_for_al(l,o.station,o.row,ptr.data());if(o.active){require(old.arithmetic&&pred.arithmetic_valid&&finite_array(pred.uv)&&finite_array(old.uv),"old/new active forward is invalid");max_uv=std::max(max_uv,std::hypot(pred.uv[0]-old.uv[0],pred.uv[1]-old.uv[1]));++active_UV_verified;}indices.push_back(old.i);old_stations.push_back(old.station);new_stations.push_back(o.station);}
 require(max_world<1e-13&&max_uv<1e-7&&std::equal(before_block.begin(),before_block.begin()+4,block.values.begin()),"old world/UV or original carrier changed beyond floating-point equivalence");std::filesystem::create_directories(out);auto binary=[&](const auto&values,const std::string&name,const std::string&dtype){const auto file=out/name;{std::ofstream f(file,std::ios::binary);f.write(reinterpret_cast<const char*>(values.data()),std::streamsize(values.size()*sizeof(values[0])));if(!f)throw std::runtime_error("cap rechart binary write failed");}return Json{{"file",file.string()},{"sha256",eventio::file_sha256(file)},{"dtype",dtype},{"shape",Json::array({values.size()})}};};
 Json report={{"schema","rinkfit.actual_source_supported_cap168_runtime_consumption.v1"},{"request",cfg.at(key)},{"input_model",request.at("activity_model")},{"source_packet",request.at("source_packet")},{"source_qualification",request.at("source_geometry_qualification")},{"engineering_weights_unchanged",cfg.at("engineering_dense_source_weights_v1")},{"source_prefix_consumed_before_transform",true},{"material_index",168},{"path_index",1},{"geometry_block",40},{"old_block_values",before_block},{"new_block_values",block.values},{"old_station_to_new_scale",scale},{"recharted_raw_rows",saved.size()},{"recharted_active_parent_prefix_rows",prefix_active},{"active_forward_rows_verified",active_UV_verified},{"S01_active_tail_scalar_references",S01_cap},{"S01_original_carrier_first4_byteexact",true},{"maximum_old_world_coordinate_delta",max_world},{"maximum_initial_active_UV_delta_px",max_uv},{"rechart_arrays",{{"packet_rows",binary(indices,"packet_rows.u64","<u8")},{"old_station",binary(old_stations,"old_station.f64","<f8")},{"new_station",binary(new_stations,"new_station.f64","<f8")}}},{"new_domain_bounded_by_current_ice_scene",true},{"physical_endpoint","unknown"},{"new_endpoint_is_a_measurement",false},{"camera_scene_optics_changed",false},{"raw_UV_ID_PTS_Query_W_qualification_or_weight_bits_changed",false},{"quality_improvement_claimed",false},{"passed",true}};eventio::atomic_json(out/"receipt.json",report);return report;
